package main

import (
	"fmt"
	"sync"
)

func worker(id int, jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {
	defer wg.Done()
	for j := range jobs {
		results <- j * j // pretend this is real work
	}
	_ = id
}

func main() {
	jobs := make(chan int, 100)
	results := make(chan int, 100)
	var wg sync.WaitGroup

	// spin up 100,000 goroutines — this would be unthinkable with OS threads
	for w := 1; w <= 100_000; w++ {
		wg.Add(1)
		go worker(w, jobs, results, &wg)
	}

	for j := 1; j <= 100_000; j++ {
		jobs <- j
	}
	close(jobs)

	wg.Wait()
	close(results)

	sum := 0
	for r := range results {
		sum += r
	}
	fmt.Println("sum:", sum)
}

// TCP is a transport-layer protocol.
// In Node.js, the net module provides TCP sockets.
// The application does not manually implement
// sequence numbers, ACKs, retransmissions, etc.
// TCP handles those details underneath.

import net from 'node:net'

const server = net.createServer((socket) => {
  console.log('client connected:', socket.remoteAddress)

  socket.on('data', (chunk) => {
    socket.write(chunk) // echo the received data
  })

  socket.on('end', () => {
    console.log('client finished sending data')
  })
})

server.listen(4000, () => {
  console.log('TCP server listening on port 4000')
})

